def create_annual_returns_chart(annual):
    """Create annual returns bar chart."""
    fig, ax = plt.subplots(figsize=(14, 6))
    fig.patch.set_facecolor(COLORS['chart_bg'])
    ax.set_facecolor(COLORS['chart_bg'])

    colors = [COLORS['positive'] if x >= 0 else COLORS['negative'] for x in annual['Return']]
    bars = ax.bar(annual.index, annual['Return'], color=colors, alpha=0.8, edgecolor='white', linewidth=0.5)

    ax.axhline(y=0, color='black', linewidth=0.5)
    ax.set_xlabel('Year', fontsize=11, color=COLORS['text'])
    ax.set_ylabel('Return (%)', fontsize=11, color=COLORS['text'])
    ax.set_title('Nike Inc. - Annual Returns (2000–2025)', fontsize=14, fontweight='bold', color=COLORS['primary'])
    ax.grid(True, alpha=0.3, axis='y')

    # Add value labels on bars
    for bar, val in zip(bars, annual['Return']):
        height = bar.get_height()
        ax.annotate(f'{val:.1f}%',
                    xy=(bar.get_x() + bar.get_width()/2, height),
                    xytext=(0, 3 if height >= 0 else -10),
                    textcoords='offset points',
                    ha='center', va='bottom' if height >= 0 else 'top',
                    fontsize=8, color=COLORS['text'])

    plt.tight_layout()

    buf = BytesIO()
    plt.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=COLORS['chart_bg'])
    plt.close()
    buf.seek(0)
    return base64.b64encode(buf.getvalue()).decode()

def create_drawdown_chart(df):
    """Create drawdown chart."""
    rolling_max = df['Close'].cummax()
    drawdown = (df['Close'] - rolling_max) / rolling_max * 100

    fig, ax = plt.subplots(figsize=(14, 5))
    fig.patch.set_facecolor(COLORS['chart_bg'])
    ax.set_facecolor(COLORS['chart_bg'])

    ax.fill_between(df['Date'], drawdown, 0, alpha=0.5, color=COLORS['negative'])
    ax.plot(df['Date'], drawdown, color=COLORS['negative'], linewidth=0.8)

    ax.set_xlabel('Date', fontsize=11, color=COLORS['text'])
    ax.set_ylabel('Drawdown (%)', fontsize=11, color=COLORS['text'])
    ax.set_title('Nike Inc. - Maximum Drawdown (Peak-to-Trough Decline)', fontsize=14, fontweight='bold', color=COLORS['primary'])
    ax.grid(True, alpha=0.3)
    ax.xaxis.set_major_locator(mdates.YearLocator(2))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    plt.xticks(rotation=45)

    plt.tight_layout()

    buf = BytesIO()
    plt.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=COLORS['chart_bg'])
    plt.close()
    buf.seek(0)
    return base64.b64encode(buf.getvalue()).decode()

def format_volume(vol):
    """Format volume in millions/billions."""
    if vol >= 1e9:
        return f'{vol/1e9:.2f}B'
    elif vol >= 1e6:
        return f'{vol/1e6:.2f}M'
    else:
        return f'{vol/1e3:.0f}K'

