#!/usr/bin/env python3
"""
Nike Inc. (NKE) Historical Stock Performance Analysis Report Generator
Generates a professional HTML report for investors.
"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
from matplotlib.gridspec import GridSpec
import base64
from io import BytesIO
from datetime import datetime
import os

# Configuration
DATA_PATH = '/app/benchmark/data.csv'
OUTPUT_PATH = '/app/output/final_report.html'

# Color scheme (professional, muted financial palette)
COLORS = {
    'primary': '#1a365d',      # Deep navy
    'secondary': '#2c5282',    # Medium blue
    'accent': '#3182ce',        # Bright blue
    'positive': '#276749',      # Green
    'negative': '#c53030',      # Red
    'neutral': '#718096',       # Gray
    'background': '#f7fafc',   # Light gray
    'text': '#2d3748',          # Dark gray
    'chart_bg': '#ffffff',      # White
}

def load_data():
    """Load and preprocess the Nike stock data."""
    df = pd.read_csv(DATA_PATH)
    df['Date'] = pd.to_datetime(df['Date'], format='M/D/YYYY')
    df = df.sort_values('Date').reset_index(drop=True)
    df['Return'] = df['Close'].pct_change()
    df['Daily_Range'] = df['High'] - df['Low']
    return df

def compute_kpis(df):
    """Compute all required KPIs."""
    start_price = df['Close'].iloc[0]
    end_price = df['Close'].iloc[-1]
    start_date = df['Date'].iloc[0]
    end_date = df['Date'].iloc[-1]

    # Cumulative Return
    cumulative_return = ((end_price / start_price) - 1) * 100

    # CAGR
    years = (end_date - start_date).days / 365.25
    cagr = ((end_price / start_price) ** (1/years) - 1) * 100

    # Maximum Drawdown
    rolling_max = df['Close'].cummax()
    drawdown = (df['Close'] - rolling_max) / rolling_max * 100
    max_drawdown = drawdown.min()

    # Annualized Volatility
    daily_vol = df['Return'].std()
    annualized_vol = daily_vol * np.sqrt(252) * 100

    # Average Daily Volume
    avg_volume = df['Volume'].mean()

    return {
        'cumulative_return': cumulative_return,
        'cagr': cagr,
        'max_drawdown': max_drawdown,
        'annualized_volatility': annualized_vol,
        'avg_daily_volume': avg_volume,
        'start_price': start_price,
        'end_price': end_price,
        'start_date': start_date,
        'end_date': end_date,
        'years': years
    }

def compute_annual_returns(df):
    """Compute annual returns for each year."""
    df['Year'] = df['Date'].dt.year
    annual = df.groupby('Year').agg({
        'Close': ['first', 'last'],
        'Volume': 'mean',
        'High': 'max',
        'Low': 'min'
    })
    annual.columns = ['Open', 'Close', 'Avg_Volume', 'High', 'Low']
    annual['Return'] = (annual['Close'] - annual['Open']) / annual['Open'] * 100
    annual['Range'] = (annual['High'] - annual['Low']) / annual['Low'] * 100
    return annual

def compute_decade_returns(df):
    """Compute decade-level returns."""
    df['Decade'] = (df['Date'].dt.year // 10) * 10
    decades = df.groupby('Decade').agg({
        'Close': ['first', 'last']
    })
    decades.columns = ['Start', 'End']
    decades['Return'] = (decades['End'] - decades['Start']) / decades['Start'] * 100
    return decades

def create_price_chart(df):
    """Create the main price trend chart."""
    fig, ax = plt.subplots(figsize=(14, 6))
    fig.patch.set_facecolor(COLORS['chart_bg'])
    ax.set_facecolor(COLORS['chart_bg'])

    ax.plot(df['Date'], df['Close'], color=COLORS['primary'], linewidth=1.2, label='NKE Close Price')

    # Add all-time high line
    ath_idx = df['Close'].idxmax()
    ath_date = df.loc[ath_idx, 'Date']
    ath_price = df.loc[ath_idx, 'Close']
    ax.axhline(y=ath_price, color=COLORS['positive'], linestyle='--', alpha=0.7, label=f'All-Time High: ${ath_price:.2f}')
    ax.scatter([ath_date], [ath_price], color=COLORS['positive'], s=50, zorder=5)

    # Add all-time low line
    atl_idx = df['Close'].idxmin()
    atl_date = df.loc[atl_idx, 'Date']
    atl_price = df.loc[atl_idx, 'Close']
    ax.axhline(y=atl_price, color=COLORS['negative'], linestyle='--', alpha=0.7, label=f'All-Time Low: ${atl_price:.2f}')

    ax.set_xlabel('Date', fontsize=11, color=COLORS['text'])
    ax.set_ylabel('Adjusted Close Price (USD)', fontsize=11, color=COLORS['text'])
    ax.set_title('Nike Inc. (NKE) - 26-Year Price History (2000–2026)', fontsize=14, fontweight='bold', color=COLORS['primary'])
    ax.legend(loc='upper left', framealpha=0.9)
    ax.grid(True, alpha=0.3)

    # Format x-axis
    ax.xaxis.set_major_locator(mdates.YearLocator(2))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    plt.xticks(rotation=45)

    plt.tight_layout()

    buf = BytesIO()
    plt.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=COLORS['chart_bg'])
    plt.close()
    buf.seek(0)
    return base64.b64encode(buf.getvalue()).decode()

def create_volatility_chart(df):
    """Create rolling volatility chart."""
    df['Rolling_Vol_252'] = df['Return'].rolling(window=252).std() * np.sqrt(252) * 100

    fig, ax = plt.subplots(figsize=(14, 5))
    fig.patch.set_facecolor(COLORS['chart_bg'])
    ax.set_facecolor(COLORS['chart_bg'])

    ax.fill_between(df['Date'], df['Rolling_Vol_252'], alpha=0.4, color=COLORS['accent'])
    ax.plot(df['Date'], df['Rolling_Vol_252'], color=COLORS['accent'], linewidth=0.8)

    # Mark crisis periods
    crises = [
        ('Dot-com Bust', '2000-03-01', '2002-10-01'),
        ('2008 Financial Crisis', '2008-01-01', '2009-12-31'),
        ('COVID-19 Crash', '2020-01-01', '2020-04-30'),
    ]
