    ax.set_ylabel('Annualized Volatility (%)', fontsize=11, color=COLORS['text'])
    ax.set_title('Nike 252-Day Rolling Volatility (Annualized)', fontsize=14, fontweight='bold', color=COLORS['primary'])
    ax.legend(loc='upper right', fontsize=9, framealpha=0.9)
    ax.grid(True, alpha=0.3)
    ax.xaxis.set_major_locator(mdates.YearLocator(2))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    plt.xticks(rotation=45)

    plt.tight_layout()

    buf = BytesIO()
    plt.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=COLORS['chart_bg'])
    plt.close()
    buf.seek(0)
    return base64.b64encode(buf.getvalue()).decode()

def create_volume_chart(df):
    """Create volume analysis chart."""
    df['Rolling_Volume_50'] = df['Volume'].rolling(window=50).mean()

    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(14, 8), gridspec_kw={'height_ratios': [2, 1]})
    fig.patch.set_facecolor(COLORS['chart_bg'])

    # Volume bars with price overlay
    colors = [COLORS['positive'] if df['Close'].iloc[i] >= df['Open'].iloc[i] else COLORS['negative']
              for i in range(len(df))]
    ax1.bar(df['Date'], df['Volume']/1e6, color=colors, alpha=0.6, width=1)
    ax1.plot(df['Date'], df['Rolling_Volume_50']/1e6, color=COLORS['primary'], linewidth=1, label='50-Day Avg Volume')

    ax1.set_ylabel('Volume (Millions)', fontsize=11, color=COLORS['text'])
    ax1.set_title('Nike Inc. - Trading Volume & Price Context', fontsize=14, fontweight='bold', color=COLORS['primary'])
    ax1.legend(loc='upper right')
    ax1.grid(True, alpha=0.3)
    ax1.xaxis.set_major_locator(mdates.YearLocator(2))
    ax1.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))

    # Price chart below
    ax2.plot(df['Date'], df['Close'], color=COLORS['primary'], linewidth=1)
    ax2.set_ylabel('Close Price (USD)', fontsize=11, color=COLORS['text'])
    ax2.set_xlabel('Date', fontsize=11, color=COLORS['text'])
    ax2.grid(True, alpha=0.3)
    ax2.xaxis.set_major_locator(mdates.YearLocator(2))
    ax2.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    plt.xticks(rotation=45)

    plt.tight_layout()

    buf = BytesIO()
    plt.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=COLORS['chart_bg'])
    plt.close()
    buf.seek(0)
    return base64.b64encode(buf.getvalue()).decode()

def create_annual_returns_chart(annual):
