    for year, ret in top_years.items():
        html += f"""                        <tr><td>{year}</td><td class="positive">{ret:+.1f}%</td></tr>
"""

    html += f"""                    </table>
                </div>
                <div>
                    <h4 style="color: #c53030;">Bottom 5 Worst Years</h4>
                    <table class="data-table">
                        <tr><th>Year</th><th>Return</th></tr>
"""

    bottom_years = annual['Return'].nsmallest(5)
    for year, ret in bottom_years.items():
        html += f"""                        <tr><td>{year}</td><td class="negative">{ret:+.1f}%</td></tr>
"""

    html += f"""                    </table>
                </div>
            </div>

            <h3>Decade Performance</h3>
            <table class="data-table">
                <tr><th>Decade</th><th>Start Price</th><th>End Price</th><th>Return</th></tr>
"""

    for decade, row in decades.iterrows():
        ret_str = f"{row['Return']:.1f}%" if not pd.isna(row['Return']) else "N/A"
        ret_class = "positive" if row['Return'] >= 0 else "negative" if row['Return'] < 0 else ""
        html += f"""                <tr><td>{decade}s</td><td>${row['Start']:.2f}</td><td>${row['End']:.2f}</td><td class="{ret_class}">{ret_str}</td></tr>
"""

    html += """            </table>
