def main():
    print("Loading Nike stock data...")
    df = load_data()

    print("Computing KPIs...")
    kpis = compute_kpis(df)

    print("Computing annual returns...")
    annual = compute_annual_returns(df)

    print("Computing decade returns...")
    decades = compute_decade_returns(df)

    print("Generating charts...")
    charts = {
        'price': create_price_chart(df),
        'volatility': create_volatility_chart(df),
        'volume': create_volume_chart(df),
        'annual_returns': create_annual_returns_chart(annual),
        'drawdown': create_drawdown_chart(df)
    }

    print("Generating HTML report...")
    html = generate_html_report(df, kpis, annual, decades, charts)

    print(f"Writing report to {OUTPUT_PATH}...")
    with open(OUTPUT_PATH, 'w', encoding='utf-8') as f:
        f.write(html)

    print(f"✓ Report generated successfully: {OUTPUT_PATH}")
    print(f"\nKey Metrics:")
    print(f"  Cumulative Return: {kpis['cumulative_return']:.1f}%")
    print(f"  CAGR: {kpis['cagr']:.2f}%")
    print(f"  Max Drawdown: {kpis['max_drawdown']:.1f}%")
    print(f"  Annualized Volatility: {kpis['annualized_volatility']:.1f}%")
    print(f"  Avg Daily Volume: {format_volume(kpis['avg_daily_volume'])}")

if __name__ == '__main__':
    main()

